def taxonomy_by_incident_type() -> dict[str, dict[str, Any]]:
    return {record["incident_type"]: record for record in default_incident_taxonomy()}


def _entry(
    incident_family: str,
    incident_type: str,
    severity: str,
    kill_switch_state: str,
    response_decision: str,
) -> dict[str, Any]:
    record = {
        "taxonomy_version": INCIDENT_RESPONSE_VERSION,
        "incident_family": incident_family,
        "incident_type": incident_type,
        "default_severity": severity,
        "default_kill_switch_state": kill_switch_state,
        "default_response_decision": response_decision,
        "paper_only": True,
        "live_blocked": True,
    }
    return record
